-- Catálogo confiável para conferir arrumação e limitar objetos válidos na casa.
create table public.casa_catalogo(id text primary key, inicial jsonb not null);
alter table public.casa_catalogo enable row level security;
create policy casa_catalogo_ler on public.casa_catalogo for select to authenticated using(true);
revoke all on public.casa_catalogo from public,anon,authenticated;
grant select on public.casa_catalogo to authenticated;
