e","versao":0,"local":"chao","lugar":"Casa","x":260,"y":545,"origem":{"x":260,"y":545},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":["escova","pasta","toalha","sabonete"],"mordidas":0,"noite":false,"comodo":"banheiro"},{"id":"escova","tipo":"pegavel","versao":0,"local":"consumido","lugar":"Casa","x":210,"y":570,"origem":{"x":210,"y":570},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"banheiro"},{"id":"pasta","tipo":"pegavel","versao":0,"local":"consumido","lugar":"Casa","x":230,"y":570,"origem":{"x":230,"y":570},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"banheiro"},{"id":"toalha","tipo":"pegavel","versao":0,"local":"consumido","lugar":"Casa","x":250,"y":570,"origem":{"x":250,"y":570},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"banheiro"},{"id":"sabonete","tipo":"pegavel","versao":0,"local":"consumido","lugar":"Casa","x":270,"y":570,"origem":{"x":270,"y":570},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"banheiro"},{"id":"balanco-casa","tipo":"assento","versao":0,"local":"chao","lugar":"Casa","x":260,"y":335,"origem":{"x":260,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"quintal"},{"id":"mangueira","tipo":"agua","versao":0,"local":"chao","lugar":"Casa","x":510,"y":335,"origem":{"x":510,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"quintal"},{"id":"casinha-pet","tipo":"recipiente","versao":0,"local":"chao","lugar":"Casa","x":760,"y":335,"origem":{"x":760,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"quintal"},{"id":"churrasqueira","tipo":"aparelho","versao":0,"local":"chao","lugar":"Casa","x":1010,"y":335,"origem":{"x":1010,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"quintal"},{"id":"canteiro","tipo":"aparelho","versao":0,"local":"chao","lugar":"Casa","x":260,"y":545,"origem":{"x":260,"y":545},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"quintal"},{"id":"maquina","tipo":"aparelho","versao":0,"local":"chao","lugar":"Casa","x":260,"y":335,"origem":{"x":260,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"lavanderia"},{"id":"varal","tipo":"recipiente","versao":0,"local":"chao","lugar":"Casa","x":510,"y":335,"origem":{"x":510,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"lavanderia"},{"id":"cesto","tipo":"recipiente","versao":0,"local":"chao","lugar":"Casa","x":760,"y":335,"origem":{"x":760,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":["roupa-suja"],"mordidas":0,"noite":false,"comodo":"lavanderia"},{"id":"roupa-suja","tipo":"pegavel","versao":0,"local":"consumido","lugar":"Casa","x":710,"y":360,"origem":{"x":710,"y":360},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"lavanderia"},{"id":"ferro","tipo":"aparelho","versao":0,"local":"chao","lugar":"Casa","x":1010,"y":335,"origem":{"x":1010,"y":335},"trava":null,"ocupantes":[],"aberto":false,"ligado":false,"modo":0,"itens":[],"mordidas":0,"noite":false,"comodo":"lavanderia"}]$casa$::jsonb);

-- Ledger privado de recompensas: uma moeda por evento confirmado, sem valores do cliente.
create table private.premios_casa(
 usuario uuid not null references public.profiles(id) on delete cascade,
 evento text not null check(evento in ('arrumar','tapete','estrelas','patinho')),
 dia date not null, primary key(usuario,evento,dia)
);
alter table private.premios_casa enable row level security;
revoke all on private.premios_casa from public,anon,authenticated;
create or replace function public.guardar_objetos(p_lugar text,p_estados jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
 v_uid uuid:=auth.uid(); v_item jsonb;v_s jsonb;v_id text;v_base integer;v_nova integer;
 v_atual public.objetos_estado;v_ate bigint;v_jogador uuid;v_instancia uuid;v_o jsonb;v_ocupantes jsonb;v_resultado jsonb:='[]';v_chave text;
begin
 if v_uid is null then raise exception 'nao autenticado';end if;
 if p_lugar is null or char_length(p_lugar) not between 1 and 40 or p_estados is null or jsonb_typeof(p_estados)<>'array' then raise exception 'dados invalidos';end if;
 if jsonb_array_length(p_estados) not between 1 and 256 then raise exception 'lote invalido';end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(p_estados))<>jsonb_array_length(p_estados) then raise exception 'objeto repetido';end if;
 perform 1 from public.profiles where id=v_uid for update;
 if not found then raise exception 'perfil inexistente';end if;
 v_ate:=floor(extract(epoch from clock_timestamp())*1000)+8000;
 for v_item in select value from jsonb_array_elements(p_estados) order by value->>'id' loop
  v_id:=v_item->>'id';v_s:=v_item->'estado';
  if v_id is null or v_id !~ '^[a-z][a-z0-9-]{0,79}$' or jsonb_typeof(v_s)<>'object' or v_s->>'id'<>v_id or v_s->>'lugar'<>p_lugar then raise exception 'objeto invalido';end if;
  if v_s-array['id','tipo','versao','local','lugar','x','y','origem','trava','ocupantes','aberto','ligado','modo','itens','mordidas','noite','comodo','prontoEm']<>'{}'::jsonb then raise exception 'campo invalido';end if;
  if v_s ? 'comodo' and coalesce(v_s->>'comodo','') not in ('sala','quarto','cozinha','banheiro','quintal','lavanderia') then raise exception 'comodo invalido';end if;
  if v_s ? 'prontoEm' and (jsonb_typeof(v_s->'prontoEm')<>'number' or (v_s->>'prontoEm')::numeric<0 or (v_s->>'prontoEm')::numeric>v_ate+1000) then raise exception 'prazo invalido';end if;
  if p_lugar='Casa' and (coalesce(v_s->>'comodo','') not in ('sala','quarto','cozinha','banheiro','quintal','lavanderia') or not exists(select 1 from public.casa_catalogo c where c.id=v_id and c.inicial->>'tipo'=v_s->>'tipo')) then raise exception 'objeto da casa invalido';end if;
  if coalesce(v_s->>'tipo','') not in ('pegavel','assento','cama','aparelho','recipiente','porta','agua') or coalesce(v_s->>'local','') not in ('chao','mao','mochila','consumido') then raise exception 'tipo invalido';end if;
  foreach v_chave in array array['versao','x','y','modo','mordidas'] loop
   if coalesce(jsonb_typeof(v_s->v_chave),'')<>'number' then raise exception 'numero invalido';end if;
  end loop;
  foreach v_chave in array array['aberto','ligado','noite'] loop
   if coalesce(jsonb_typeof(v_s->v_chave),'')<>'boolean' then raise exception 'estado invalido';end if;
  end loop;
  if (v_s->>'x')::numeric not between 0 and 1280 or (v_s->>'y')::numeric not between 0 and 720 or (v_s->>'mordidas')::integer not between 0 and 3 or (v_s->>'modo')::integer not between 0 and 2 then raise exception 'limite invalido';end if;
  if coalesce(jsonb_typeof(v_s->'origem'),'')<>'object' or coalesce(jsonb_typeof(v_s->'ocupantes'),'')<>'array' or coalesce(jsonb_typeof(v_s->'itens'),'')<>'array' then raise exception 'colecao invalida';end if;
  if coalesce(jsonb_typeof(v_s->'origem'->'x'),'')<>'number' or coalesce(jsonb_typeof(v_s->'origem'->'y'),'')<>'number' then raise exception 'origem invalida';end if;
  if (v_s->'origem'->>'x')::numeric not between 0 and 1280 or (v_s->'origem'->>'y')::numeric not between 0 and 720 then raise exception 'origem invalida';end if;
  if jsonb_array_length(v_s->'ocupantes')>6 or jsonb_array_length(v_s->'itens')>6 then raise exception 'capacidade invalida';end if;
  v_base:=(v_item->>'base')::integer;v_nova:=(v_s->>'versao')::integer;
  if v_base is null or v_base<0 or v_nova<=v_base then raise exception 'versao invalida';end if;
  insert into public.objetos_estado(dono,lugar,objeto_id,estado,versao)
    values(v_uid,p_lugar,v_id,jsonb_set(v_s,'{versao}','0'),0) on conflict do nothing;
  select * into v_atual from public.objetos_estado where dono=v_uid and lugar=p_lugar and objeto_id=v_id for update;
  if v_atual.versao<>v_base then raise exception using errcode='40001',message='versao antiga';end if;
  if v_s->>'local' in ('mao','mochila') then
   if coalesce(jsonb_typeof(v_s->'trava'),'')<>'object' then raise exception 'posse invalida';end if;
   v_jogador:=(v_s->'trava'->>'jogador')::uuid;v_instancia:=(v_s->'trava'->>'instancia')::uuid;
   if v_jogador is null or v_instancia is null or (v_jogador<>v_uid and not exists(select 1 from public.rooms r join public.room_members m on m.room_id=r.id where r.dono_id=v_uid and r.ativa and m.aprovado and m.user_id=v_jogador)) then raise exception 'jogador nao aprovado';end if;
   v_s:=jsonb_set(v_s,'{trava,ate}',to_jsonb(v_ate));
  else v_s:=jsonb_set(v_s,'{trava}','null');end if;
  v_ocupantes:='[]';
  for v_o in select value from jsonb_array_elements(v_s->'ocupantes') loop
   v_jogador:=(v_o->>'jogador')::uuid;v_instancia:=(v_o->>'instancia')::uuid;
   if v_jogador is null or v_instancia is null or v_o->>'snap' is null or (v_o->>'snap')::integer not between 0 and 5 or (v_jogador<>v_uid and not exists(select 1 from public.rooms r join public.room_members m on m.room_id=r.id where r.dono_id=v_uid and r.ativa and m.aprovado and m.user_id=v_jogador)) then raise exception 'ocupante nao aprovado';end if;
   v_ocupantes:=v_ocupantes||jsonb_build_array(jsonb_set(v_o,'{ate}',to_jsonb(v_ate)));
  end loop;
  if (select count(distinct value->>'snap') from jsonb_array_elements(v_ocupantes))<>jsonb_array_length(v_ocupantes) then raise exception 'snap ocupado';end if;
  v_s:=jsonb_set(v_s,'{ocupantes}',v_ocupantes);
  update public.objetos_estado set estado=v_s,versao=v_nova,atualizado_em=clock_timestamp() where dono=v_uid and lugar=p_lugar and objeto_id=v_id;
  v_resultado:=v_resultado||jsonb_build_array(v_s);
 end loop;
 if exists(select 1 from public.objetos_estado o where dono=v_uid and lugar=p_lugar and estado->>'local' in ('mao','mochila') and (estado->'trava'->>'ate')::numeric>v_ate-8000
 group by estado->'trava'->>'jogador'
 having count(*) filter(where estado->>'local'='mao')>1 or count(*) filter(where estado->>'local'='mochila')>6) then raise exception 'inventario cheio';end if;
 if exists(select 1 from public.objetos_estado o cross join lateral jsonb_array_elements(o.estado->'ocupantes') e where o.dono=v_uid and o.lugar=p_lugar and (e->>'ate')::numeric>v_ate-8000 group by e->>'jogador' having count(*)>1) then raise exception 'avatar ja sentado';end if;
 return jsonb_build_object('estados',v_resultado,'agora',v_ate-8000);
end $$;
revoke all on function public.guardar_objetos(text,jsonb) from public,anon;
grant execute on function public.guardar_objetos(text,jsonb) to authenticated;

create function public.recompensar_casa(p_dono uuid,p_evento text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=auth.uid();v_s jsonb;v_dia date;v_n integer;v_saldo integer;
begin
 if v_uid is null or p_dono is null or (v_uid<>p_dono and not private.amigo_do_mundo(p_dono)) then raise exception 'nao autorizado';end if;
 if p_evento is null or p_evento not in ('arrumar','tapete','estrelas','patinho') then raise exception 'evento invalido';end if;
 perform 1 from public.profiles where id in(p_dono,v_uid) order by id for update;
 if p_evento='arrumar' then
  if exists(select 1 from public.casa_catalogo c left join public.objetos_estado o on o.objeto_id=c.id and o.dono=p_dono and o.lugar='Casa'
   where o.objeto_id is null or o.versao<1 or o.estado->>'local'<>c.inicial->>'local' or o.estado->>'comodo'<>c.inicial->>'comodo'
   or o.estado->'x'<>c.inicial->'x' or o.estado->'y'<>c.inicial->'y' or o.estado->'trava'<>'null'::jsonb or jsonb_array_length(o.estado->'ocupantes')<>0) then raise exception 'casa ainda fora do lugar';end if;
  v_dia:=(now() at time zone 'America/Sao_Paulo')::date;
 else
  select estado into v_s from public.objetos_estado where dono=p_dono and lugar='Casa' and objeto_id=case p_evento when 'tapete' then 'tapete' when 'estrelas' then 'luz-quarto' else 'banheira' end;
  if v_s is null or (v_s->>'modo')::integer<>2 then raise exception 'surpresa ainda escondida';end if;
  v_dia:='1970-01-01'::date;
 end if;
 insert into private.premios_casa(usuario,evento,dia) values(v_uid,p_evento,v_dia) on conflict do nothing;
 get diagnostics v_n=row_count;
 if v_n=1 then perform set_config('mtmw.interno','sim',true);update public.profiles set moedas=moedas+1 where id=v_uid;perform set_config('mtmw.interno','nao',true);end if;
 select moedas into v_saldo from public.profiles where id=v_uid;
 return jsonb_build_object('moedas',v_saldo,'premiada',v_n=1);
end $$;
revoke all on function public.recompensar_casa(uuid,text) from public,anon;
grant execute on function public.recompensar_casa(uuid,text) to authenticated;
